static void lower_node(Context& c, IR& ir, const Node& n){
 switch(n.kind){
 case Kind::Butterfly: { auto r=add_reg(ir); ir.code.push_back({op(n.kind),(uint16_t)r,(uint16_t)n.args.size(),0,16}); break; }
 case Kind::Gate: case Kind::Delta: case Kind::Recur: case Kind::Route: case Kind::Seal: { auto r=add_reg(ir); ir.code.push_back({op(n.kind),(uint16_t)r,0,0,(int32_t)n.imm}); break; }
 default: { auto r=add_reg(ir); ir.code.push_back({op(n.kind),(uint16_t)r,0,0,(int32_t)n.imm}); }
 }
}
IR compile(Context& c,const Ast& a){ IR ir{}; for(const auto& n:a.nodes) lower_node(c,ir,n); if(ir.regs>c.target.regs_per_thread) fail(c,{},"register contract exceeded"); return ir; }
std::string emit_p45(const IR& ir){ std::string out; for(const auto& x:ir.code){ out += "P45."+std::to_string(x.op)+" R"+std::to_string(x.dst)+"\\n"; } return out; }
std::string emit_sass(const IR& ir){ std::string out; for(const auto& x:ir.code){ out += "OP "+std::to_string(x.op)+" R"+std::to_string(x.dst)+"\\n"; } return out; }
